CREATE OR REPLACE FUNCTION public.validate_followup_schedule() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status <> 'cancelled' AND EXISTS(SELECT 1 FROM public.orders WHERE id=NEW.order_id AND status='cancelled') THEN RAISE EXCEPTION 'Cancelled orders cannot receive followups'; END IF; IF NEW.due_at <= NEW.occurred_at THEN RAISE EXCEPTION 'Followup must be after the event'; END IF; IF btrim(NEW.note)='' THEN RAISE EXCEPTION 'Confirmation reason is required'; END IF; IF TG_OP='UPDATE' AND OLD.status='sent' THEN RAISE EXCEPTION 'Sent followups cannot be rescheduled'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_followup_schedule BEFORE INSERT OR UPDATE ON public.after_sales_followups FOR EACH ROW EXECUTE FUNCTION public.validate_followup_schedule();